// /402 witness — what real x402 client libraries did with this server's paywalls (session 36, 2026-10-29; docs/spec-x402-witness.md).
// The rows live in src/witness-x402-data.js (GENERATED by scripts/witness-parse-x402.mjs from the committed capture) and are served as the
// "x402" family of /clients.jsonl. This module computes, from those rows only, the findings and the witness block on GET /402 and the home
// page. Nothing here is typed except the vocabulary and the honesty boundary: every figure, list and client name is read from a row.
// Sentences describe what the caller received and what went on the wire, never a verdict. The x402 v2 specification says nothing about
// spending limits, about retrying after a second 402 or about a 500 after a payment, so signing for a very large amount with a client's
// defaults and refusing to are both inside what it allows; the reference (REFERENCE_X402) is derived from the control's offer.

import { WITNESS_X402, CLIENTS_X402, REFERENCE_X402, OBSERVATIONS_X402 } from './witness-x402-data.js';

const W = WITNESS_X402 || {};
const ALL = () => (Array.isArray(OBSERVATIONS_X402) ? OBSERVATIONS_X402 : []);
const xRows = () => ALL().filter((o) => o && o.client && o.client.role === 'client');
const xControls = () => ALL().filter((o) => o && o.client && o.client.role === 'control');
const xClients = () => (Array.isArray(CLIENTS_X402) ? CLIENTS_X402 : []).filter((c) => c.role === 'client');
const xName = (id) => ((Array.isArray(CLIENTS_X402) ? CLIENTS_X402 : []).find((c) => c.id === id) || { name: id }).name;
const xList = (a) => (a.length ? a.join(', ') : 'none');
const xPlural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const xScenarios = () => [...new Set(xRows().map((o) => o.scenario))];
const xObs = (client, scenario) => xRows().find((o) => o.client.id === client && o.scenario === scenario);
const xWire = (o) => (o && (o.wire || (o.fetches && o.fetches[0] && o.fetches[0].wire))) || {};
const xOut = (o) => (o && o.outcome) || 'unknown';
const xCaller = (o) => (o && o.fetches && o.fetches[0] && o.fetches[0].caller) || null;
const xNames = (rows) => rows.map((o) => xName(o.client.id)).sort();

// atomic USDC units (6 decimals) as a number a reader can scan: "1,000,000 USDC", "0.01 USDC"; the unit is test USDC on a testnet network
const usdc = (atomic) => {
  try {
    const v = BigInt(String(atomic));
    const whole = v / 1000000n;
    const frac = (v % 1000000n).toString().padStart(6, '0').replace(/0+$/, '');
    return `${whole.toLocaleString('en-US')}${frac ? '.' + frac : ''} USDC`;
  } catch {
    return `${atomic} atomic units`;
  }
};

const OUTCOME_WORDS = {
  'delivered/decodable': 'delivered the body with a decodable receipt',
  'delivered/undecodable': 'delivered the body with a receipt that did not decode',
  'delivered/absent': 'delivered the body with no receipt',
  'handed-back/402': 'handed back a 402',
  'handed-back/500': 'handed back a 500',
  'handed-back/504': 'handed back a 504',
  'handed-back/503': 'handed back the harness budget\'s 503',
  'raised/before-signing': 'raised before signing anything',
  'raised/after-signing': 'raised after signing',
  'harness-timeout': 'was still running when the harness cap fired',
  'request-failed': 'never reached the server',
};
const outWords = (k) => OUTCOME_WORDS[k] || (/^handed-back\/\d{3}$/.test(k) ? `handed back a ${k.slice(-3)}` : k);

// What the client put on the wire, as words: nothing signed, or the first authorization's value and the header it used, and how often it signed again.
const signedWords = (o) => {
  const w = xWire(o);
  if (!w.signed) return 'signed nothing';
  const again = w.resigned > 0 ? `, then signed again ${xPlural(w.resigned, 'time')}` : '';
  return `signed ${w.signed_value_atomic != null ? usdc(w.signed_value_atomic) : 'an authorization'} with ${w.payment_header}${again}`;
};
const answer = (o) => `${signedWords(o)} and ${outWords(xOut(o))}`;

const groupBy = (rows, fn) => {
  const m = new Map();
  for (const o of rows) {
    const k = fn(o);
    if (!m.has(k)) m.set(k, []);
    m.get(k).push(o);
  }
  return [...m.entries()].sort((a, b) => b[1].length - a[1].length || String(a[0]).localeCompare(String(b[0])));
};
const render = (groups, total) => groups.map(([k, v]) => `${v.length === total ? `all ${v.length} clients` : `${xList(xNames(v))}`} ${k}`).join('; ');

/** gated(out, list, expected, sentence): a sentence about named clients that renders only while the computed list it was written for matches. */
export function gated(out, list, expected, sentence) {
  const have = [...list].sort().join('|');
  const want = [...expected].sort().join('|');
  if (have === want) out.push(sentence);
}

const offerOf = (scenario) => {
  const ctl = xControls().find((o) => o.scenario === scenario);
  return ctl && ctl.control && ctl.control.offer ? ctl.control.offer : null;
};
const refSays = (scenario) => {
  const r = (REFERENCE_X402 || {})[scenario];
  if (!r) return null;
  const sign = r.signing ? r.signing : 'unspecified';
  return `${sign}${r.note ? `, since ${r.note}` : ''}`;
};

export function x402Findings() {
  const rows = xRows();
  if (!rows.length) return [];
  const out = [];
  const N = xClients().length || new Set(rows.map((o) => o.client.id)).size;
  const scen = xScenarios();
  const tally = Object.entries(rows.reduce((m, o) => ((m[xOut(o)] = (m[xOut(o)] || 0) + 1), m), {})).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${v} ${k}`).join(', ');
  const signedRows = rows.filter((o) => xWire(o).signed);
  out.push(
    `${N} x402 client ${N === 1 ? 'library or wrapper' : 'libraries or wrappers'} (${xList(xClients().map((c) => c.name))}) were each handed one throwaway Base Sepolia payer and asked to GET each of ${scen.length} /402 URLs once, with the library's defaults and no payment header sent by the harness — ${xPlural(rows.length, 'row')} in all. Every payment header below is one the client chose to send. By what the caller received: ${tally}. ${signedRows.length} of ${rows.length} rows signed at least one authorization.`,
  );

  // generation split, from the pay cell: which header each client paid with
  const payRows = rows.filter((o) => o.scenario === 'pay');
  if (payRows.length) {
    const hdr = groupBy(payRows.filter((o) => xWire(o).signed), (o) => xWire(o).payment_header);
    const unsigned = payRows.filter((o) => !xWire(o).signed);
    out.push(`On pay, the one paywall that settles (0.01 test USDC): ${hdr.length ? hdr.map(([k, v]) => `${xPlural(v.length, 'client')} (${xList(xNames(v))}) paid with ${k}`).join('; ') : 'no client signed'}${unsigned.length ? `; ${xList(xNames(unsigned))} signed nothing` : ''}. The server reads PAYMENT-SIGNATURE (x402 v2) and X-PAYMENT (x402 v1) alike and answers each in its own generation's receipt header.`);
    const dec = payRows.filter((o) => xOut(o) === 'delivered/decodable');
    const other = payRows.filter((o) => xOut(o) !== 'delivered/decodable');
    out.push(`On pay, ${dec.length} of ${payRows.length} clients delivered the body with a decodable receipt${dec.length ? ` (${xList(xNames(dec))})` : ''}${other.length ? `; the rest: ${render(groupBy(other, answer), other.length)}` : ''}.`);
    // A paid request this server answered 402 is the facilitator chain's verify verdict for that minute, relayed as the 402's error;
    // the sentence names it so a non-delivery on pay is never read as a property of the client.
    const payRejected = other.map((o) => { const ex = ((o.fetches && o.fetches[0] && o.fetches[0].exchanges) || []).find((e) => e.x402 && (e.x402.payment_signature || e.x402.x_payment)); const err = ex && ex.x402 && ex.x402.payment_required ? ex.x402.payment_required.error : null; return [o, ex ? ex.status : null, err]; }).filter(([, st]) => st === 402);
    const payRejOk = payRejected.filter(([o]) => xWire(o).value_matches_offer === true && xWire(o).to_matches_offer === true);
    const payRejOther = payRejected.filter(([o]) => !(xWire(o).value_matches_offer === true && xWire(o).to_matches_offer === true));
    if (payRejected.length) out.push(`On pay, the paid request of ${xPlural(payRejected.length, 'client')} (${xList(xNames(payRejected.map(([o]) => o)))}) was answered 402 by this server with the facilitator's verify verdict as the error (${xList([...new Set(payRejected.map(([, , e]) => JSON.stringify(String(e || '').split('\n')[0].slice(0, 60))))])})${payRejOther.length ? `; ${xList(xNames(payRejOther.map(([o]) => o)))} signed a value or address other than the offer's (${xList(payRejOther.map(([o]) => `${usdc(xWire(o).signed_value_atomic)} to ${String(xWire(o).signed_to || '').slice(0, 10)}…`))})` : ''}${payRejOk.length && !payRejOther.length ? '; each had signed the offered amount to the offered address, so that is a statement about the Base Sepolia facilitator chain at that minute, not about the client' : ''}.`);
  }

  // overpriced: the amount the server asked for, and who signed it
  const over = rows.filter((o) => o.scenario === 'overpriced');
  if (over.length) {
    const off = offerOf('overpriced');
    const offerAmt = off && off.accepts && off.accepts[0] ? off.accepts[0].amount : null;
    const signed = over.filter((o) => xWire(o).signed);
    const notSigned = over.filter((o) => !xWire(o).signed);
    const byVal = groupBy(signed, (o) => usdc(xWire(o).signed_value_atomic));
    out.push(
      `On overpriced${offerAmt != null ? `, where the offer asks for ${usdc(offerAmt)}` : ''}, ${signed.length} of ${over.length} clients signed an authorization with their defaults${byVal.length ? ` (${byVal.map(([k, v]) => `${k}: ${xList(xNames(v))}`).join('; ')})` : ''}; ${notSigned.length} did not sign${notSigned.length ? ` (${render(groupBy(notSigned, (o) => outWords(xOut(o))), notSigned.length)})` : ''}. The x402 specification has no spending limit, so a client that signs and one that stops are both inside it; the authorization expires after 300 seconds and this server discards it.`,
    );
  }

  // never: signs, is told no, and what each client does next
  const nev = rows.filter((o) => o.scenario === 'never');
  if (nev.length) {
    const s = nev.filter((o) => xWire(o).signed);
    const byRe = groupBy(s, (o) => xWire(o).resigned);
    const cut = nev.filter((o) => o.budget_exhausted);
    out.push(
      `On never, a paywall that answers 402 to every payment, ${s.length} of ${nev.length} clients signed${byRe.length ? `; signing again after the second 402: ${byRe.map(([k, v]) => `${xList(xNames(v))} ${k} ${k === 1 ? 'time' : 'times'}`).join('; ')}` : ''}${cut.length ? `; ${xList(xNames(cut))} ${cut.length === 1 ? 'was' : 'were'} cut off by the harness budget after ${xPlural(Math.max(...cut.map((o) => xWire(o).requests || 0)), 'request')} and stopped there` : ''}. Outcomes: ${render(groupBy(nev, (o) => outWords(xOut(o))), nev.length)}.`,
    );
  }

  // the remaining named scenarios, one generic line each, then the malformed flavors
  const generic = (name, lead) => {
    const rs = rows.filter((o) => o.scenario === name);
    if (!rs.length) return;
    const ref = refSays(name);
    out.push(`On ${name.replace(/^broken\//, '')}${lead ? `, ${lead}` : ''}${ref ? ` (reference: ${ref})` : ''}: ${render(groupBy(rs, answer), rs.length)}.`);
  };
  const leads = {
    reject: 'a paywall that rejects every payment with a reason',
    slow: 'a paywall that sits on a paid request and answers 504',
    crash: 'a paywall that answers 500 after the payment',
    'bad-receipt': 'a paywall whose receipt header is not decodable',
    'wrong-network': 'whose only option is on a network that does not exist',
    'broken/empty-accepts': 'an offer whose accepts list is empty',
    'broken/decimal-amount': 'an offer whose amount is a decimal string',
    'broken/v1-body': 'a spec-valid x402 v1 offer in the body and no PAYMENT-REQUIRED header',
    'broken/missing-header': 'a 402 with no PAYMENT-REQUIRED header',
  };
  for (const name of ['reject', 'slow', 'crash', 'bad-receipt', 'wrong-network', 'broken/empty-accepts', 'broken/decimal-amount', 'broken/v1-body', 'broken/missing-header']) generic(name, leads[name]);
  const named = new Set(['pay', 'never', 'overpriced', ...Object.keys(leads)]);
  const rest = scen.filter((s) => !named.has(s));
  for (const name of rest) generic(name, '');

  // v1-body / missing-header: which generation read the body
  for (const name of ['broken/v1-body', 'broken/missing-header']) {
    const rs = rows.filter((o) => o.scenario === name);
    if (!rs.length) continue;
    const readers = groupBy(rs.filter((o) => xWire(o).signed), (o) => xWire(o).payment_header);
    out.push(`On ${name.replace(/^broken\//, '')}, where the offer carries no PAYMENT-REQUIRED header, ${rs.filter((o) => xWire(o).signed).length} of ${rs.length} clients signed${readers.length ? ` (${readers.map(([k, v]) => `${xList(xNames(v))} with ${k}`).join('; ')})` : ''}; the others signed nothing.`);
  }

  // ---- GATED EXPLANATIONS. Each sentence is written by hand from the client's source as docs/survey-x402-clients-2026-10-29.md read it
  // (sections cited), and renders only while the computed id list it was written for still holds, so a re-capture that moves a list drops
  // the explanation instead of misattributing it (the #23 rule).
  const idsWhere = (scenario, pred) => rows.filter((o) => o.scenario === scenario && pred(o)).map((o) => o.client.id);
  const S = 'docs/survey-x402-clients-2026-10-29.md';
  gated(out, idsWhere('overpriced', (o) => xWire(o).signed), ['faremeter-fetch', 'thirdweb-x402', 'x402-go', 'x402-axios-v1'],
    `Why those four signed on overpriced, as their sources read (${S}, section 1 "Default spending limits" and sections 2.4-2.9): none of them has a spending limit unless the caller sets one. thirdweb's fetchWithPayment tests options.maxValue only when it is given (fetchWithPayment.js:85-88), Faremeter's exact EVM handler signs requirements.amount as offered (payment-evm exact/client.js:39-45), the Go client's selector has no amount check (client.go:228-262), and x402-axios 1.1.0's interceptor has none (index.mjs:15-49).`);
  gated(out, idsWhere('overpriced', (o) => !xWire(o).signed), ['x402-fetch-v2', 'x402-axios-v2', 'agentkit-x402', 'x402-httpx', 'x402-requests', 'x402-fetch-v1'],
    `Why the other six refused before signing (${S}, section 1): @x402/core's default spend control is $1 per payment on its default assets (client/index.mjs:21, DEFAULT_MAX_AMOUNT_PER_PAYMENT), shared by @x402/fetch, @x402/axios and AgentKit, which wraps @x402/fetch; the Python client has the same $1 default (client_base.py:185); x402-fetch 1.2.0 caps at 0.1 USDC (index.mjs:15) and throws "Payment amount exceeds maximum allowed".`);
  gated(out, [...idsWhere('never', (o) => (xWire(o).resigned || 0) > 0).map((id) => `again:${id}`), ...idsWhere('never', (o) => xWire(o).signed && xWire(o).payment_requests === 1).map((id) => `once:${id}`)], ['again:faremeter-fetch', 'once:x402-fetch-v2', 'once:x402-axios-v2', 'once:thirdweb-x402', 'once:x402-fetch-v1', 'once:x402-axios-v1', 'once:agentkit-x402', 'once:x402-httpx', 'once:x402-requests', 'once:x402-go'],
    `Why Faremeter alone signed again on never (${S}, sections 2.2-2.9): @faremeter/fetch repeats the whole sequence (unpaid request, sign, paid request) up to retryCount + 1 = 3 times with a doubling 100 ms delay whenever the paid request is answered 402 (fetch.js:72-82), then throws WrappedFetchError carrying the last 402 (fetch.js:83-86). Every other roster client makes exactly one paid retry and hands the second 402 back or raises it (@x402/fetch index.mjs:75; @x402/axios index.mjs:59-71; AgentKit through @x402/fetch, section 2.7; thirdweb fetchWithPayment.js:123; x402-fetch index.mjs:39-41; x402-axios index.mjs:28-30; Python httpx.py:102 and requests.py:110; Go http/client.go:168).`);
  gated(out, idsWhere('broken/v1-body', (o) => !xWire(o).signed), ['x402-fetch-v2', 'x402-axios-v2', 'x402-go'],
    `Why @x402/fetch, @x402/axios and the Go client signed nothing on v1-body (${S}, sections 2.2 and 2.9): all three read a v1 body (@x402/core chunk-4NCAR6KR.mjs:2257-2266; Go http/client.go:436-466) but each pays it only with a v1 scheme registered, and the harness registered the exact EVM scheme for eip155:84532 in the quick-start form (x402Client.fromConfig with an ExactEvmScheme; Register(network, ...) in Go), which registers x402 v2 only; @x402/core then throws "No client registered for x402 version: 1" (client/index.mjs:253-257) and Go returns unsupported_scheme. @x402/evm's registerExactEvmScheme helper also registers the v1 scheme for the matching plain network names (chunk-GNHGHC3E.mjs:152-160), as the Python register_exact_evm_client helper does (register.py:27-76), ${['x402-httpx', 'x402-requests'].every((id) => rows.some((o) => o.scenario === 'broken/v1-body' && o.client.id === id && xWire(o).payment_header === 'X-PAYMENT')) ? ', which is why both Python clients signed the v1 body with X-PAYMENT' : ''}.`);
  gated(out, idsWhere('broken/missing-header', (o) => xWire(o).signed), ['thirdweb-x402', 'x402-go'],
    `Why thirdweb and the Go client signed on missing-header (${S}, sections 2.4 and 2.9): both read the 402 body when the PAYMENT-REQUIRED header is absent and take the version from the body (thirdweb's parsePaymentRequired, x402/schemas.js:97-106 and fetchWithPayment.js:59-65; the Go RoundTripper, http/client.go:436-466), where @x402/core, the Python client and Faremeter accept a body only when it says x402Version 1 (chunk-4NCAR6KR.mjs:2257-2266; x402_http_client_base.py:121-150; @faremeter/fetch internal.js:36-66).`);
  gated(out, idsWhere('broken/no-extra', (o) => !xWire(o).signed), ['x402-fetch-v2', 'x402-axios-v2', 'agentkit-x402', 'x402-fetch-v1', 'x402-axios-v1'],
    `Why @x402/fetch, @x402/axios and AgentKit raised before signing on no-extra (${S}, section 2.2): @x402/evm's scheme requires extra.name and extra.version before it signs (chunk-KWP3UD2B.mjs:71); the two v1 libraries read only the body, which carries no accepts on this flavor (section 2.5). Faremeter signed because its handler falls back to the asset's default EIP-712 name and version when extra is absent (payment-evm exact/client.js:47-63, section 2.6); where thirdweb, the Go client and the Python client took their domain values from is not traced in the survey.`);
  gated(out, idsWhere('broken/version-99', (o) => !xWire(o).signed), ['x402-fetch-v2', 'x402-axios-v2', 'agentkit-x402', 'faremeter-fetch', 'x402-fetch-v1', 'x402-axios-v1'],
    `Why six clients refused the x402Version 99 offer (${S}, sections 2.2, 2.5 and 2.6): @x402/core throws "No client registered for x402 version: 99" (client/index.mjs:253-257), Faremeter's schema requires version 2 (internal.js:36-66), and the two v1 libraries read only the body, which carries no accepts on this flavor. thirdweb signed because it takes the version from the payload when it is a number and names the payment header after it (x402/schemas.js:106, x402/headers.js:9-12, section 2.4); why the Go and Python clients signed is not traced in the survey.`);


  const timeouts = rows.filter((o) => xOut(o) === 'harness-timeout');
  const failed = rows.filter((o) => xOut(o) === 'request-failed');
  const budget = rows.filter((o) => o.budget_exhausted);
  const label = (o) => `${xName(o.client.id)} on ${o.scenario.replace(/^broken\//, '')}`;
  const aborted = rows.filter((o) => !['harness-timeout', 'request-failed'].includes(xOut(o)) && !o.budget_exhausted).flatMap((o) => (((o.fetches && o.fetches[0] && o.fetches[0].exchanges) || []).filter((e) => e.client_aborted === true && e.status === 0)).map(() => o));
  const abortedNote = aborted.length ? ` — except ${xPlural(aborted.length, 'exchange')} where the client hung up before any response byte arrived, with no x-badhttp-version to read (${xList(aborted.map(label))})` : '';
  out.push(`${timeouts.length} of ${rows.length} rows hit the harness's cap${timeouts.length ? ` (${xList(timeouts.map(label))})` : ''}, ${budget.length} were cut off by the request budget${budget.length ? ` (${xList(budget.map(label))})` : ''} and ${failed.length} failed to land${failed.length ? ` (${xList(failed.map(label))})` : ''}. Every other row is a response this server sent, read back from the wire with its x-badhttp-version on every exchange it answered${abortedNote}.`);
  return out;
}

const countBy = (rows, fn) => rows.reduce((m, o) => { const k = fn(o); m[k] = (m[k] || 0) + 1; return m; }, {});

export function x402Witness() {
  const rows = xRows();
  const controls = xControls();
  const cl = xClients();
  const bucket = (n) => (n == null ? 'unsigned' : n === 0 ? '0' : n === 1 ? '1' : n <= 5 ? '2-5' : '6+');
  return {
    measured: W.probed || null,
    request_budget: W.request_budget ?? null,
    badhttp_version_observed: W.badhttp_version_observed || null,
    worker_version: W.worker_version || null,
    observations: rows.length,
    control_rows: controls.length,
    scenarios: xScenarios().length,
    data: 'https://badhttp.dev/clients.jsonl',
    data_note:
      'Every observation is a row of /clients.jsonl with family "x402", joined to /corpus.jsonl by corpus_id; /clients indexes them with the class, ' +
      'outcome, description, wire and reference legends and the per-scenario disagreement. The findings below are a reading of those rows, not a second source.',
    what_this_is:
      `${cl.length} real x402 client libraries and wrappers plus a raw-wire control (curl), one fresh working directory and one fresh client process per cell, each handed the project's throwaway Base Sepolia payer (test USDC, no dollar value) and the library's defaults. ` +
      'Each cell asks the client to GET one /402 URL once; the harness never sends a payment header for a client, so every PAYMENT-SIGNATURE or X-PAYMENT in a row is one the client chose to send, for the amount and on the network it chose. ' +
      'It is a DATED CAPTURE, not a live measurement. Every request the client sent went through a local recording reverse proxy that forwarded it to this service over TLS and returned the response verbatim; the proxy decodes the x402 headers into a summary (never a raw signature), and it cuts a client off after a fixed request budget so a client that signs again forever is bounded by the harness and never by the zone rate limit. ' +
      'The x402 v2 specification says the client reads PAYMENT-REQUIRED, selects a requirement it can satisfy, retries with PAYMENT-SIGNATURE and reads PAYMENT-RESPONSE; it says nothing about spending limits, about retrying after a second 402, or about a 500 after a payment. ' +
      'So each row is described against a reference derived from the control\'s wire exchange: what the offer the server made admits (an offer with nothing a Base Sepolia payer can satisfy admits no payment; /402/pay admits one and delivers a receipt). ' +
      'An outcome describes what the caller received, never a verdict: a client that signs for a very large amount with its defaults and one that stops are both doing something the specification allows, and the finding is the difference. ' +
      'Every figure, list and client name in this block is computed from the rows, never typed, except inside the gated explanations: each of those is written by hand from the client\'s source as docs/survey-x402-clients-2026-10-29.md read it, and renders only while the computed facts it names still hold.',
    reading_this:
      'An outcome is a description of what the caller received (delivered, handed back a status, raised) qualified by whether the client signed; it is never a verdict on the client. The reference is derived from the control\'s offer, not typed: signing is no-payment-possible, payment-expected or unspecified, and result is stated only for pay.',
    clients: cl.map((c) => `${c.name} ${c.version} (${c.class})`),
    control: (Array.isArray(CLIENTS_X402) ? CLIENTS_X402 : []).filter((c) => c.role === 'control').map((c) => `${c.name} ${c.version}`),
    outcome_counts: countBy(rows, xOut),
    signed_counts: {
      signed: rows.filter((o) => xWire(o).signed).length,
      not_signed: rows.filter((o) => !xWire(o).signed).length,
      resigned_at_least_once: rows.filter((o) => (xWire(o).resigned || 0) >= 1).length,
      receipt_decodable: rows.filter((o) => xWire(o).receipt === 'decodable').length,
      receipt_undecodable: rows.filter((o) => xWire(o).receipt === 'undecodable').length,
      receipt_absent: rows.filter((o) => xWire(o).receipt === 'absent').length,
      resigned_buckets: countBy(rows.filter((o) => xWire(o).signed), (o) => bucket(xWire(o).resigned)),
    },
    disagreement_by_scenario: W.disagreement_by_scenario || {},
    answers_by_scenario: W.answers_by_scenario || {},
    reference: REFERENCE_X402 || {},
    reference_note: 'REFERENCE in the /clients x402 family block: per scenario, signing (no-payment-possible | payment-expected | unspecified) and result (delivered/decodable for pay only), derived from the control\'s offer, with a note naming the clause that produced it',
    findings: x402Findings(),
    what_this_cannot_say:
      'Anything over HTTPS or HTTP/2 (every client spoke HTTP/1.1 to a loopback recorder); what a client does with mainnet funds (the payer holds test USDC on Base Sepolia only, and no cell offers eip155:8453); ' +
      'whether a client that signed for 1,000,000 USDC would have been charged by a server that kept the authorization (this one discards it, and the expiry is 300 seconds); a hosted-wallet or smart-wallet signer ' +
      '(every roster client signs with a local key); a client configured with a spending limit it does not set by default (the configuration is the library\'s defaults); anything after the harness caps or the request budget.',
    not_in_roster: Array.isArray(W.not_in_roster) ? W.not_in_roster : [],
    reproduce:
      'Run scripts/x402-witness/all.sh in the source (it needs X402_WITNESS_PAYER_KEY, a throwaway Base Sepolia key holding test USDC only, and refuses to run with TLS verification off or while the smoke suite runs), ' +
      'then node scripts/witness-parse-x402.mjs on the capture it writes to regenerate src/witness-x402-data.js. By hand: point the row\'s client at the row\'s url with the payer registered for eip155:84532 and nothing else changed, ' +
      'and compare the requests it sent and what the caller received with the row; for the reference, fetch the same url with curl -sS --http1.1 and read the offer. Pace the calls against the zone limit of 100 per 10 s, ' +
      'and treat a response without x-badhttp-version as no observation.',
    capture: W.capture || null,
    run_log: W.run_log || null,
  };
}
